/**
 * Legacy dsRead* and dse* workloads.
 * These reproduce the exact tables and specs from acceptance_workloads/ directories
 * that were generated by the original DeltaSuite-based capture system.
 *
 * Run: ./bin/generate-workload.sh tables/core_reads_legacy.scala
 */
import io.delta.workload.WorkloadGenerator._

// ---------------------------------------------------------------------------
// dsReadAfterOptimize: 10 single-row appends then OPTIMIZE (DVs enabled)
// ---------------------------------------------------------------------------
workload("dsReadAfterOptimize", "Read after OPTIMIZE") { w =>
  w.sql("""CREATE TABLE tbl (value INT) USING delta
    TBLPROPERTIES ('delta.enableDeletionVectors' = 'true')""")
  (1 to 10).foreach { i =>
    w.sql(s"INSERT INTO tbl VALUES ($i)")
  }
  w.sql("OPTIMIZE tbl")
  val t = w.table("tbl")
  w.read(t)
  w.snapshot(t)
}

