  w.sql("INSERT INTO tbl SELECT id FROM range(11, 16)")
  val t = w.table("tbl")
  w.read(t)
  w.read(t, version = 0)
  w.read(t, version = 1)
  w.read(t, version = 2)
  w.snapshot(t)
}

